"""kernels/muse_decode_layer/measure_layer_v1.py (C22a', MEASUREMENT-ONLY, generated by tools/gen_measure_layer_v1.py).

No GPU:  file rules, kernel_fn / prepare are sonnet_v5 verbatim, in sync with the generator, the large-M CUDA source is the MoE problem's sonnet_v4 with only the route kernel
         changed (local_start from the device tensor, wrap rule), the TMAPOOL kernel really emits cp.async.bulk.tensor for sm_90 (offline AOT compile), the budget guard.
Dev GPU (RTX 2060, sm_75, FP16 stand-ins for BF16, small configs): the whole study end to end for T = 1 and 128 (correctness checks, CUPTI replays, output lines), and the
         large-M route + GEMMs through NVRTC against the organisers' reference experts.
Run:     tools/heavy.sh .venv/bin/python -m pytest -q tests/test_measure_layer_v1.py
         LM_NVRTC=1 tools/heavy.sh .venv/bin/python -m pytest -q tests/test_measure_layer_v1.py -k largem    (the NVRTC part, ~12 min)"""
import importlib.util
import os
import re
import sys
from pathlib import Path

import pytest
import torch

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT))
sys.path.insert(0, str(ROOT / "tests"))

from tools import local_check as lc  # noqa: E402

PROBLEM = "muse_decode_layer"
MEASURE = ROOT / "kernels" / PROBLEM / "measure_layer_v1.py"
V5 = ROOT / "kernels" / PROBLEM / "sonnet_v5.py"
MOE4 = ROOT / "kernels" / "muse_moe_w4a16" / "sonnet_v4.py"
needs_cuda = pytest.mark.skipif(not torch.cuda.is_available(), reason="needs a CUDA GPU")


def _load(name, path):
    spec = importlib.util.spec_from_file_location(name, path)
    m = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(m)
    return m


@pytest.fixture()
def mod():
    return _load("_measure_layer_v1", MEASURE)


@pytest.fixture(scope="module")
def ref():
    return lc.Loaded(PROBLEM, V5).ref


def test_source_rules_and_in_sync_with_generator():
    src = MEASURE.read_text()
    compile(src, "measure_layer_v1.py", "exec")
    lines = src.splitlines()
    assert lines[0] == "# okc: problem=muse_decode_layer" and "MEASUREMENT-ONLY" in lines[1] and "NEVER submit" in lines[1]
    for banned in ("subprocess", "urllib", "requests", "socket", "os.system", ".item(", ".cpu(", "environ", "import os", ".tolist(", "reference.py'", "from reference"):
        assert banned not in src.replace("problems/muse_decode_layer/reference.py", ""), banned
    assert "torch.profiler" in src      # tools/okc_run.py refuses to submit files that use it
    from tools import gen_measure_layer_v1 as gen
    assert gen.build() == src, "regenerate: .venv/bin/python tools/gen_measure_layer_v1.py"
    assert "MEASUREMENT-ONLY" not in V5.read_text() and "def _ml_" not in V5.read_text()


def test_kernel_fn_and_prepare_are_sonnet_v5_verbatim():
    v5 = V5.read_text().splitlines(keepends=True)
    src = MEASURE.read_text()
    assert "".join(v5[1:]).rstrip("\n") in src
    assert "def kernel_fn(data, state):\n    if HAVE_SGLANG:\n        return _kernel_sglang(data, state)\n    return _kernel_torch(data, state)" in src
    # the wrapper only adds the study after the original prepare() and returns the original state unchanged
    i = src.index("_ml_orig_prepare = prepare")
    assert "state = _ml_orig_prepare(weights)" in src[i:] and src[i:].rstrip().endswith("return state")
    assert src.count("def kernel_fn(") == 1


def test_largem_source_is_the_moe_problems_except_the_route_kernels_local_start(mod):
    import difflib

    moe = _load("_moe4", MOE4)
    a = moe._LARGEM_EXTRA_SRC.splitlines() + moe._LARGEM_HOST_SRC.splitlines()
    b = mod._ML_LARGEM_EXTRA_SRC.splitlines() + mod._ML_LARGEM_HOST_SRC.splitlines()
    diff = [d for d in difflib.unified_diff(a, b, lineterm="", n=0) if d[:1] in "+-" and d[:3] not in ("+++", "---")]
    assert len(diff) <= 20, "\n".join(diff)
    joined = "\n".join(diff)
    assert "lo_ptr" in joined and "& 255" in joined and "data_ptr<int>(), (int)nloc" in joined
    assert mod._ML_LM_CFG == {k: v for k, v in moe.LARGEM_CFG.items()}
    assert mod.LM_TC == moe.LM_TC and mod.LM_CTW == moe.LM_CTW and mod.LM_MAX_M == moe.LM_MAX_M


def test_budget_constants_fit_the_judges_prepare_limit(mod):
    assert mod._ML_BUDGET_S <= 270 and mod._ML_FRONT_S < mod._ML_C24_S < mod._ML_BUDGET_S
    assert mod._ML_MAX_BYTES <= 14000


def test_config_tables_are_valid(mod):
    for t, cfgs in mod._ML_RPAR_CFG.items():
        for name, bn, bk, split, warps, stages in cfgs:
            assert 256 % bn == 0 and (8192 // split) % bk == 0 and 8192 % split == 0 and split <= 64, (t, name)
            if t <= 32:
                assert (256 // bn) * split >= 256, (t, name)        # RPAR: at least 256 CTAs
    for name, bn, bk, warps, stages in mod._ML_TMA_CFG:
        assert bk * 2 <= 512 and bk <= 256 and 4096 % bn == 0   # boxDim <= 256, inner box a multiple of 16 B
    assert mod._ML_NAMES.count("base") == 1


@needs_cuda
def test_tma_kernel_emits_bulk_tensor_copies_for_sm90(mod):
    import triton
    from triton.backends.compiler import GPUTarget
    from triton.compiler import ASTSource

    for stages in (4, 6):
        sig = {"x_ptr": "*bf16", "w_desc": "tensordesc<bf16[32,256]>", "out_ptr": "*bf16", "M": "i32", "N": "i32", "K": "i32", "stride_xm": "i32", "stride_om": "i32"}
        c = triton.compile(ASTSource(fn=mod._ml_gemv_tma, signature=sig, constexprs={"BM": 16, "BN": 32, "BK": 256}), target=GPUTarget("cuda", 90, 32),
                           options={"num_warps": 4, "num_stages": stages})
        assert len(re.findall(r"cp\.async\.bulk\.tensor", c.asm["ptx"])) >= stages - 1, stages


@needs_cuda
def test_router_fixup_kernel_compiles_for_sm90(mod):
    import triton
    from triton.backends.compiler import GPUTarget
    from triton.compiler import ASTSource

    sig = {"x_ptr": "*fp32", "hi_ptr": "*bf16", "lo_ptr": "*bf16", "out_ptr": "*fp32", "part_ptr": "*fp32", "done_ptr": "*i32", "M": "i32", "stride_x": "i32"}
    for bm, bn, bk, split, sx in ((16, 64, 128, 64, True), (256, 32, 32, 32, False)):
        sig["x_ptr"] = "*fp32" if sx else "*bf16"
        consts = {"BM": bm, "BN": bn, "BK": bk, "SPLIT": split, "SPLIT_X": sx, "K": 8192, "N": 256}
        c = triton.compile(ASTSource(fn=mod._ml_router_fix, signature=sig, constexprs=consts), target=GPUTarget("cuda", 90, 32), options={"num_warps": 4, "num_stages": 3})
        assert c.metadata.shared < 200 * 1024


