# ------------------------------------------------------------------------------------------------ dev GPU: the study end to end
def _small_configs(mod):
    """sm_75 has 64 KB of smem: shrink every pipeline (the study's logic, not its timings, is under test)."""
    for k in list(mod._CFG):
        bn, bk, sp, w, st = mod._CFG[k]
        mod._CFG[k] = (min(bn, 32), min(bk, 64), sp, 4, 2)
    mod._ML_RPAR_CFG = {t: (("A", 32, 64, 32, 4, 2), ("B", 16, 64, 16, 4, 2)) for t in (1, 8, 16, 32, 128, 256)}
    mod._ML_POOLSMEM_CFG = (("ps1", 32, 64, 1, 4, 2), ("ps2", 16, 64, 1, 4, 2))
    mod._ML_OSHOT_CFG = (("A", 16, 256, 4, 2), ("B", 16, 128, 4, 2))


@pytest.fixture(scope="module")
def weights(ref):
    return ref.generate_weights(ref.WEIGHTS_SEED, device="cuda")


@needs_cuda
def test_study_end_to_end_on_the_dev_gpu(mod, weights, capsys):
    _small_configs(mod)
    mod._ML_TS = (1, 128)
    mod._ML_REPS = 5
    mod._ML_FRONT_S = 1e9
    state = mod.prepare(weights)
    assert state is not None and "router_hi" in state
    out = capsys.readouterr().out
    assert len(out) <= 14000
    first = [ln for ln in out.splitlines() if ln.startswith("ML C22a'")]
    assert first and out.index(first[0]) < out.index("B layer")        # the summary comes first
    assert "cupti=ok" in first[0]
    b = [ln for ln in out.splitlines() if ln.startswith("B layer")]
    pat = re.compile(r"^B layer T=(\d+) seed=(\d+) E=(\d+) \| (\w+) side_end=[\d.]+ main_idle=[\d.]+ pool=[\d.-]+ rout=[\d.-]+ ln=[\d.]+$")
    assert b and all(pat.match(ln) for ln in b), [ln for ln in b if not pat.match(ln)][:3]
    names = {(int(pat.match(ln).group(1)), pat.match(ln).group(4)) for ln in b}
    assert {(1, v) for v in ("base", "order", "rpar", "ordrpar", "psm", "psm2", "psmr", "psmrpar")} <= names
    assert {(128, v) for v in ("base", "order", "mm", "ordmm", "bm", "ordbm", "rs2")} <= names
    assert {int(pat.match(ln).group(2)) for ln in b} == {11, 12, 13}
    k = [ln for ln in out.splitlines() if ln.startswith("K layer")]
    assert len(k) == 2
    for ln in k:
        assert "order bit1/ids0" in ln
        for tag in re.findall(r"(rpar\w|bm\w|mm) ([\d.e+-]+)/ids(\d+)/w([\d.e+-]+)/d(\d)", ln):
            assert float(tag[1]) < 1e-4 and tag[2] == "0" and float(tag[3]) < 1e-5 and tag[4] == "1", tag
        for tag in re.findall(r"(ps\d) ([\d.e+-]+)/bit(\d)", ln):
            assert tag[2] == "1", tag
    assert "RULE ORDER" in out and "RULE RBIG" in out and "RULE POOLSMEM" in out
    assert any(ln.startswith("A layer T=1 ") for ln in out.splitlines())


