@pytest.fixture(scope="module")
def lm_env(weights, ref):
    if os.environ.get("LM_NVRTC") != "1":
        pytest.skip("set LM_NVRTC=1: NVRTC builds the large-M kernels for sm_75 with the BF16 mma emulated, ~11 minutes")
    nv = pytest.importorskip("nvrtc_smallm")
    if not nv.HAVE_NVRTC or not torch.cuda.is_available():
        pytest.skip("needs NVRTC and a GPU")
    mod = _load("_measure_layer_v1_lm", MEASURE)
    sm_ext = nv.NvrtcExt(mod._SMALLM_DEVICE_SRC)
    old = mod.SMALLM_CFG
    mod.SMALLM_CFG = ((1, 4, 4, 3, 4, 4, 3), (8, 4, 4, 6, 4, 4, 6), (16, 4, 4, 12, 4, 4, 12))
    sm = mod.prepare_smallm(weights, ext=sm_ext)
    mod.SMALLM_CFG = old
    lm_ext = nv.NvrtcLargeExt(mod._SMALLM_DEVICE_SRC + mod._ML_LARGEM_EXTRA_SRC)
    return mod, sm, lm_ext


