@needs_cuda
@pytest.mark.parametrize("m,seed,start", [(20, 3, 0), (24, 5, 96), (20, 7, 240)])
def test_largem_experts_match_the_references_moe_block(lm_env, ref, weights, m, seed, start):
    mod, sm, ext = lm_env
    lm = mod._ml_lm_scratch(sm, ext)
    g = torch.Generator(device="cuda").manual_seed(seed)
    x = torch.randn((m, 4096), generator=g, device="cuda").to(torch.bfloat16)
    ids = torch.randint(0, 256, (m, 8), generator=g, device="cuda")
    ids[:, :4] = (start + torch.randint(0, 32, (m, 4), generator=g, device="cuda")) % 256      # a busy 32-expert range (it wraps for start 240)
    w = torch.rand((m, 8), generator=g, device="cuda")
    w = w / w.sum(-1, keepdim=True)
    start_t = torch.tensor([start], dtype=torch.int32, device="cuda")
    cfg = dict(nw1=4, mr1=2, ks1=8, nz1=24, nw2=4, mr2=2, ks2=8, nz2=24)      # 2060: K slices of 512 keep the smem under 64 KB
    state = {"smallm": sm, "post_expert_w": (weights["post_expert_norm"].float() + 1.0).to(torch.bfloat16)}
    assert mod._epilogue_path(m) == "triton"
    got = mod._ml_lm_experts(x, w, ids.to(torch.int32), start_t, state, lm, cfg)
    torch.cuda.synchronize()
    local = (ids - start) % 256
    full = {k: weights[k] for k in ("w13", "w13_sf", "w13_gs", "w2", "w2_sf", "w2_gs")}
    full["post_expert_norm"] = weights["post_expert_norm"]
    want = ref._experts(x.float(), local, w, full)
    rel = float((got.float() - want.float()).norm() / want.float().norm())
    assert got.shape == want.shape and rel < 1.5e-2, rel


@needs_cuda
def test_c24_flow_with_stand_in_experts(mod, weights):
    """_ml_run_c24's control flow (inputs, routing, graph + CUPTI units, ratios, rule lines) with the Marlin / large-M calls replaced by torch stand-ins."""
    _small_configs(mod)
    mod._ML_REPS = 4
    mod._ML_C24_S = 1e9
    state = mod._ml_orig_prepare(weights)
    s = mod._ml_setup(state)
    mod._experts = lambda x, w, ids, start, st: (x.float() * 2.0).to(torch.bfloat16)
    mod._ml_lm_experts = lambda x, w, ids, start, st, lm, cfg: (x.float() * 2.0).to(torch.bfloat16)
    mod._ml_lm_scratch = lambda sm, ext: {}
    mod._ml_route_check = lambda ext, lm: 0
    mod._ML_LM.update(ext=object(), thread=None)
    c_lines = []
    mod._ml_run_c24(s, mod._MLEnv(), {**state, "smallm": {"dims": {}}}, {}, c_lines)
    rows = [c for c in c_lines if isinstance(c, tuple)]
    assert [c[0] for c in rows] == [32] * 3 + [128] * 3 + [256] * 3
    assert all(c[3] == 0.0 and set(c[4]) == {"marlin", "largem"} and c[4]["marlin"]["e2e"] > 0 for c in rows)
    text = mod._ml_render({}, {}, c_lines, True)
    assert text.splitlines()[0].startswith("ML C22a'")
    assert len([ln for ln in text.splitlines() if "c24_largem" in ln]) == 9 and "RULE C24 T=128" in text and "route kernel" in text
